"""Apply the Go2 0.5 full-joint-mask RWM refactor on a server checkout.

This script is intentionally idempotent. It overwrites the small set of RWM
training/play files that are affected by the full network-level joint-mask
ablation, avoiding fragile patch context against locally modified server files.
"""

from __future__ import annotations

from pathlib import Path


REPO_ROOT = Path(__file__).resolve().parents[3]

FILES: dict[str, str] = {
    'scripts/reinforcement_learning/rwm_dataset/joint_feature_mask.py': '"""Feature-index helpers for Go2 joint-mask ablation experiments."""\n\nfrom __future__ import annotations\n\nfrom collections.abc import Iterable, Sequence\n\nimport numpy as np\nimport torch\n\nfrom scripts.reinforcement_learning.rwm_dataset.action_mask import normalize_action_mask_indices\nfrom scripts.reinforcement_learning.rwm_dataset.broken_go2 import GO2_ACTION_JOINT_NAMES\n\n\nGO2_RWM_STATE_DIM = 45\nGO2_FULL_POLICY_OBS_DIM = 48\nGO2_BASE_LIN_VEL_STATE_INDICES: tuple[int, ...] = (0, 1, 2)\n\nGO2_RWM_STATE_JOINT_FIELD_OFFSETS: dict[str, int] = {\n    "joint_pos": 9,\n    "joint_vel": 21,\n    "actuator_force": 33,\n}\n\nGO2_FULL_POLICY_OBS_JOINT_FIELD_OFFSETS: dict[str, int] = {\n    "joint_pos": 12,\n    "joint_vel": 24,\n    "last_action": 36,\n}\n\n\ndef indices_to_keep(\n    dropped_indices: int | str | Iterable[int | str] | None,\n    *,\n    dim: int,\n) -> tuple[int, ...]:\n    dropped = set(normalize_action_mask_indices(dropped_indices, action_dim=dim))\n    return tuple(idx for idx in range(int(dim)) if idx not in dropped)\n\n\ndef _joint_name_to_index(joint_name: str) -> int:\n    try:\n        return GO2_ACTION_JOINT_NAMES.index(str(joint_name))\n    except ValueError as exc:\n        raise ValueError(\n            f"Unknown Go2 joint name {joint_name!r}. Known joints: {list(GO2_ACTION_JOINT_NAMES)}"\n        ) from exc\n\n\ndef go2_joint_names_to_rwm_state_indices(\n    joint_names: Sequence[str],\n    *,\n    include_actuator_force: bool = True,\n) -> tuple[int, ...]:\n    fields = ("joint_pos", "joint_vel", "actuator_force") if include_actuator_force else ("joint_pos", "joint_vel")\n    indices: list[int] = []\n    for joint_name in dict.fromkeys(str(name) for name in joint_names if str(name)):\n        joint_idx = _joint_name_to_index(joint_name)\n        indices.extend(GO2_RWM_STATE_JOINT_FIELD_OFFSETS[field] + joint_idx for field in fields)\n    return tuple(dict.fromkeys(indices))\n\n\ndef go2_joint_names_to_policy_obs_indices(joint_names: Sequence[str]) -> tuple[int, ...]:\n    indices: list[int] = []\n    for joint_name in dict.fromkeys(str(name) for name in joint_names if str(name)):\n        joint_idx = _joint_name_to_index(joint_name)\n        indices.extend(offset + joint_idx for offset in GO2_FULL_POLICY_OBS_JOINT_FIELD_OFFSETS.values())\n    return tuple(dict.fromkeys(indices))\n\n\ndef mask_tensor_features_t(\n    values: torch.Tensor,\n    dropped_indices: int | str | Iterable[int | str] | None,\n) -> torch.Tensor:\n    keep = indices_to_keep(dropped_indices, dim=int(values.shape[-1]))\n    if len(keep) == int(values.shape[-1]):\n        return values\n    keep_t = torch.tensor(keep, dtype=torch.long, device=values.device)\n    return values.index_select(dim=-1, index=keep_t)\n\n\ndef mask_array_features_np(\n    values: np.ndarray,\n    dropped_indices: int | str | Iterable[int | str] | None,\n) -> np.ndarray:\n    keep = indices_to_keep(dropped_indices, dim=int(values.shape[-1]))\n    if len(keep) == int(values.shape[-1]):\n        return values.astype(np.float32, copy=False)\n    return values[..., list(keep)].astype(np.float32, copy=False)\n\n\ndef expand_tensor_features_t(\n    values: torch.Tensor,\n    dropped_indices: int | str | Iterable[int | str] | None,\n    *,\n    full_dim: int,\n    fill_value: float = 0.0,\n) -> torch.Tensor:\n    keep = indices_to_keep(dropped_indices, dim=int(full_dim))\n    if len(keep) == int(full_dim):\n        return values\n    if int(values.shape[-1]) != len(keep):\n        raise ValueError(f"Expected reduced dim {len(keep)}, got {int(values.shape[-1])}.")\n    out = torch.full(\n        (*values.shape[:-1], int(full_dim)),\n        float(fill_value),\n        dtype=values.dtype,\n        device=values.device,\n    )\n    out[..., list(keep)] = values\n    return out\n\n',
    'scripts/reinforcement_learning/rwm_dataset/proprioceptive_dynamics.py': '"""Proprioceptive Go2 dynamics for real-world sensor ablations.\n\nThe default model consumes ``full_state[..., 3:45]`` and predicts the full\n45-dim next state. Masked-joint experiments can additionally remove joint\nstate/action features from the network input and output while keeping the\nexternal mjlab/RWM state-action interface full-sized.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path\nfrom typing import Any\n\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\n\nfrom scripts.reinforcement_learning.rwm_dataset.joint_feature_mask import (\n    expand_tensor_features_t,\n    indices_to_keep,\n    mask_tensor_features_t,\n)\n\n\n@dataclass\nclass ProprioceptiveDynamicsConfig:\n    input_state_dim: int = 42\n    output_state_dim: int = 45\n    action_dim: int = 12\n    full_state_dim: int = 45\n    full_action_dim: int = 12\n    contact_dim: int = 4\n    termination_dim: int = 1\n    ensemble_size: int = 5\n    history_horizon: int = 32\n    forecast_horizon: int = 8\n    hidden_size: int = 256\n    num_layers: int = 2\n    min_logstd: float = -5.0\n    max_logstd: float = 2.0\n    state_loss_weight: float = 1.0\n    sequence_loss_weight: float = 1.0\n    bound_loss_weight: float = 1.0\n    kl_loss_weight: float = 0.1\n    extension_loss_weight: float = 1.0\n    contact_loss_weight: float = 1.0\n    termination_loss_weight: float = 1.0\n    loss_mode: str = "reference_autoregressive_mse"\n    dropped_state_indices: tuple[int, ...] = (0, 1, 2)\n    output_dropped_state_indices: tuple[int, ...] = ()\n    dropped_action_indices: tuple[int, ...] = ()\n\n\nclass _ProprioceptiveDynamicsMember(nn.Module):\n    def __init__(self, cfg: ProprioceptiveDynamicsConfig) -> None:\n        super().__init__()\n        self.cfg = cfg\n        input_dim = cfg.input_state_dim + cfg.action_dim\n        self.gru = nn.GRU(\n            input_size=input_dim,\n            hidden_size=cfg.hidden_size,\n            num_layers=cfg.num_layers,\n            batch_first=True,\n        )\n        self.state_mean = nn.Sequential(\n            nn.Linear(cfg.hidden_size, cfg.hidden_size),\n            nn.ELU(),\n            nn.Linear(cfg.hidden_size, cfg.output_state_dim),\n        )\n        self.state_logstd = nn.Sequential(\n            nn.Linear(cfg.hidden_size, cfg.hidden_size),\n            nn.ELU(),\n            nn.Linear(cfg.hidden_size, cfg.output_state_dim),\n        )\n        self.contact_head = nn.Sequential(\n            nn.Linear(cfg.hidden_size, cfg.hidden_size),\n            nn.ELU(),\n            nn.Linear(cfg.hidden_size, cfg.contact_dim),\n        )\n        self.termination_head = nn.Sequential(\n            nn.Linear(cfg.hidden_size, cfg.hidden_size),\n            nn.ELU(),\n            nn.Linear(cfg.hidden_size, cfg.termination_dim),\n        )\n\n    def _decode(\n        self,\n        hidden_output: torch.Tensor,\n        normalized_output_reference: torch.Tensor,\n        return_raw_logstd: bool = False,\n    ) -> tuple[torch.Tensor, ...]:\n        delta = self.state_mean(hidden_output)\n        mean = normalized_output_reference + delta\n        raw_logstd = self.state_logstd(hidden_output)\n        logstd = raw_logstd.clamp(self.cfg.min_logstd, self.cfg.max_logstd)\n        contact = self.contact_head(hidden_output)\n        termination = self.termination_head(hidden_output)\n        if return_raw_logstd:\n            return mean, logstd, raw_logstd, contact, termination\n        return mean, logstd, contact, termination\n\n    def forward(\n        self,\n        input_state_hist: torch.Tensor,\n        action_hist: torch.Tensor,\n        normalized_output_reference: torch.Tensor,\n        return_raw_logstd: bool = False,\n    ) -> tuple[torch.Tensor, ...]:\n        x = torch.cat([input_state_hist, action_hist], dim=-1)\n        out, _ = self.gru(x)\n        return self._decode(out[:, -1], normalized_output_reference, return_raw_logstd=return_raw_logstd)\n\n    def forward_with_hidden(\n        self,\n        input_state_step: torch.Tensor,\n        action_step: torch.Tensor,\n        normalized_output_reference: torch.Tensor,\n        hidden: torch.Tensor | None = None,\n        return_raw_logstd: bool = False,\n    ) -> tuple[torch.Tensor, ...]:\n        x = torch.cat([input_state_step, action_step], dim=-1)\n        out, hidden = self.gru(x, hidden)\n        outputs = self._decode(out[:, -1], normalized_output_reference, return_raw_logstd=return_raw_logstd)\n        return (*outputs, hidden)\n\n\nclass ProprioceptiveSystemDynamicsEnsemble(nn.Module):\n    """Ensemble that consumes 42-dim state histories and outputs 45-dim states."""\n\n    def __init__(self, cfg: ProprioceptiveDynamicsConfig) -> None:\n        super().__init__()\n        self.cfg = cfg\n        input_state_indices = indices_to_keep(cfg.dropped_state_indices, dim=cfg.full_state_dim)\n        output_state_indices = indices_to_keep(cfg.output_dropped_state_indices, dim=cfg.full_state_dim)\n        action_indices = indices_to_keep(cfg.dropped_action_indices, dim=cfg.full_action_dim)\n        if len(input_state_indices) != int(cfg.input_state_dim):\n            raise ValueError(\n                f"input_state_dim={cfg.input_state_dim} does not match kept input state dims "\n                f"{len(input_state_indices)} from dropped_state_indices={cfg.dropped_state_indices}."\n            )\n        if len(output_state_indices) != int(cfg.output_state_dim):\n            raise ValueError(\n                f"output_state_dim={cfg.output_state_dim} does not match kept output state dims "\n                f"{len(output_state_indices)} from output_dropped_state_indices={cfg.output_dropped_state_indices}."\n            )\n        if len(action_indices) != int(cfg.action_dim):\n            raise ValueError(\n                f"action_dim={cfg.action_dim} does not match kept action dims "\n                f"{len(action_indices)} from dropped_action_indices={cfg.dropped_action_indices}."\n            )\n        self._input_state_indices = input_state_indices\n        self._output_state_indices = output_state_indices\n        self._action_indices = action_indices\n        self.register_buffer("input_state_indices_t", torch.tensor(input_state_indices, dtype=torch.long))\n        self.register_buffer("output_state_indices_t", torch.tensor(output_state_indices, dtype=torch.long))\n        self.register_buffer("action_indices_t", torch.tensor(action_indices, dtype=torch.long))\n        self.members = nn.ModuleList([_ProprioceptiveDynamicsMember(cfg) for _ in range(cfg.ensemble_size)])\n        self.register_buffer("input_state_mean", torch.zeros(cfg.input_state_dim))\n        self.register_buffer("input_state_std", torch.ones(cfg.input_state_dim))\n        self.register_buffer("output_state_mean", torch.zeros(cfg.output_state_dim))\n        self.register_buffer("output_state_std", torch.ones(cfg.output_state_dim))\n        self.register_buffer("action_mean", torch.zeros(cfg.action_dim))\n        self.register_buffer("action_std", torch.ones(cfg.action_dim))\n\n    @property\n    def ensemble_size(self) -> int:\n        return self.cfg.ensemble_size\n\n    def set_normalizers(\n        self,\n        output_state_mean: torch.Tensor,\n        output_state_std: torch.Tensor,\n        action_mean: torch.Tensor,\n        action_std: torch.Tensor,\n    ) -> None:\n        full_state_mean = output_state_mean.to(self.output_state_mean.device)\n        full_state_std = output_state_std.to(self.output_state_std.device).clamp_min(1e-6)\n        self.output_state_mean.copy_(full_state_mean.index_select(0, self.output_state_indices_t))\n        self.output_state_std.copy_(full_state_std.index_select(0, self.output_state_indices_t))\n        self.input_state_mean.copy_(full_state_mean.index_select(0, self.input_state_indices_t))\n        self.input_state_std.copy_(full_state_std.index_select(0, self.input_state_indices_t))\n\n        action_mean = action_mean.to(self.action_mean.device)\n        action_std = action_std.to(self.action_std.device).clamp_min(1e-6)\n        if int(action_mean.shape[-1]) == int(self.cfg.full_action_dim):\n            action_mean = action_mean.index_select(0, self.action_indices_t)\n            action_std = action_std.index_select(0, self.action_indices_t)\n        self.action_mean.copy_(action_mean)\n        self.action_std.copy_(action_std)\n\n    def reduce_state(self, state: torch.Tensor) -> torch.Tensor:\n        if state.shape[-1] == self.cfg.input_state_dim:\n            return state\n        if state.shape[-1] != self.cfg.full_state_dim:\n            raise ValueError(\n                f"Expected state last dim {self.cfg.input_state_dim} or {self.cfg.full_state_dim}, "\n                f"got {state.shape[-1]}."\n            )\n        return mask_tensor_features_t(state, self.cfg.dropped_state_indices)\n\n    def reduce_output_state(self, state: torch.Tensor) -> torch.Tensor:\n        if state.shape[-1] == self.cfg.output_state_dim:\n            return state\n        if state.shape[-1] != self.cfg.full_state_dim:\n            raise ValueError(\n                f"Expected output state last dim {self.cfg.output_state_dim} or {self.cfg.full_state_dim}, "\n                f"got {state.shape[-1]}."\n            )\n        return mask_tensor_features_t(state, self.cfg.output_dropped_state_indices)\n\n    def expand_output_state(self, output_state: torch.Tensor) -> torch.Tensor:\n        return expand_tensor_features_t(\n            output_state,\n            self.cfg.output_dropped_state_indices,\n            full_dim=self.cfg.full_state_dim,\n            fill_value=0.0,\n        )\n\n    def reduce_action(self, action: torch.Tensor) -> torch.Tensor:\n        if action.shape[-1] == self.cfg.action_dim:\n            return action\n        if action.shape[-1] != self.cfg.full_action_dim:\n            raise ValueError(\n                f"Expected action last dim {self.cfg.action_dim} or {self.cfg.full_action_dim}, "\n                f"got {action.shape[-1]}."\n            )\n        return mask_tensor_features_t(action, self.cfg.dropped_action_indices)\n\n    def normalize_input_state(self, input_state: torch.Tensor) -> torch.Tensor:\n        return (input_state - self.input_state_mean) / self.input_state_std\n\n    def normalize_output_state(self, output_state: torch.Tensor) -> torch.Tensor:\n        output_state = self.reduce_output_state(output_state)\n        return (output_state - self.output_state_mean) / self.output_state_std\n\n    def denormalize_output_state(self, output_state: torch.Tensor) -> torch.Tensor:\n        return output_state * self.output_state_std + self.output_state_mean\n\n    def normalize_action(self, action: torch.Tensor) -> torch.Tensor:\n        action = self.reduce_action(action)\n        return (action - self.action_mean) / self.action_std\n\n    def _normalized_output_reference(self, input_state: torch.Tensor) -> torch.Tensor:\n        """Build a normalized residual reference for the kept output state dims."""\n\n        ref = torch.zeros(\n            *input_state.shape[:-1],\n            self.cfg.full_state_dim,\n            device=input_state.device,\n            dtype=input_state.dtype,\n        )\n        ref[..., self.input_state_indices_t] = self.normalize_input_state(input_state)\n        return self.reduce_output_state(ref)\n\n    def _member_prediction(\n        self,\n        member: _ProprioceptiveDynamicsMember,\n        state_hist: torch.Tensor,\n        action_hist: torch.Tensor,\n        return_raw_logstd: bool = False,\n    ) -> tuple[torch.Tensor, ...]:\n        input_hist = self.reduce_state(state_hist)\n        norm_input_hist = self.normalize_input_state(input_hist)\n        norm_action_hist = self.normalize_action(action_hist)\n        reference = self._normalized_output_reference(input_hist[:, -1])\n        return member(\n            norm_input_hist,\n            norm_action_hist,\n            reference,\n            return_raw_logstd=return_raw_logstd,\n        )\n\n    def _member_prediction_with_hidden(\n        self,\n        member: _ProprioceptiveDynamicsMember,\n        input_state_step: torch.Tensor,\n        action_step: torch.Tensor,\n        hidden: torch.Tensor | None = None,\n        return_raw_logstd: bool = False,\n    ) -> tuple[torch.Tensor, ...]:\n        input_state_step = self.reduce_state(input_state_step)\n        norm_input_step = self.normalize_input_state(input_state_step)\n        norm_action_step = self.normalize_action(action_step)\n        reference = self._normalized_output_reference(input_state_step[:, -1])\n        return member.forward_with_hidden(\n            norm_input_step,\n            norm_action_step,\n            reference,\n            hidden=hidden,\n            return_raw_logstd=return_raw_logstd,\n        )\n\n    def _compute_bound_loss(self, raw_logstd: torch.Tensor) -> torch.Tensor:\n        upper = F.relu(raw_logstd - self.cfg.max_logstd).square()\n        lower = F.relu(self.cfg.min_logstd - raw_logstd).square()\n        return upper.mean() + lower.mean()\n\n    def _compute_reference_autoregressive_loss(\n        self,\n        states: torch.Tensor,\n        actions: torch.Tensor,\n        next_states: torch.Tensor,\n        contacts: torch.Tensor,\n        terminations: torch.Tensor,\n        bootstrap: bool,\n    ) -> dict[str, torch.Tensor]:\n        h = self.cfg.history_horizon\n        forecast_horizon = min(self.cfg.forecast_horizon, states.shape[1] - h)\n        state_losses = []\n        sequence_losses = []\n        bound_losses = []\n        contact_losses = []\n        termination_losses = []\n\n        for member in self.members:\n            batch_indices = torch.arange(states.shape[0], device=states.device)\n            if bootstrap and states.shape[0] > 1:\n                batch_indices = torch.randint(0, states.shape[0], (states.shape[0],), device=states.device)\n\n            s = states[batch_indices]\n            a = actions[batch_indices]\n            ns = next_states[batch_indices]\n            c = contacts[batch_indices]\n            t = terminations[batch_indices]\n\n            input_state = self.reduce_state(s[:, :h])\n            action_input = a[:, :h]\n            mean, logstd, raw_logstd, contact_logits, term_logits, hidden = self._member_prediction_with_hidden(\n                member,\n                input_state,\n                action_input,\n                hidden=None,\n                return_raw_logstd=True,\n            )\n            state_loss_member = 0.0\n            bound_loss_member = 0.0\n            contact_loss_member = 0.0\n            termination_loss_member = 0.0\n            for forecast_idx in range(forecast_horizon):\n                if forecast_idx > 0:\n                    action_start = h + forecast_idx - 1\n                    action_input = a[:, action_start : action_start + 1]\n                    mean, logstd, raw_logstd, contact_logits, term_logits, hidden = self._member_prediction_with_hidden(\n                        member,\n                        input_state,\n                        action_input,\n                        hidden=hidden,\n                        return_raw_logstd=True,\n                    )\n                target_idx = h + forecast_idx - 1\n                target = self.normalize_output_state(ns[:, target_idx])\n                pred_sample = torch.randn_like(mean) * torch.exp(logstd) + mean\n                state_loss_member = state_loss_member + torch.sum((pred_sample - target).square(), dim=-1).mean()\n                bound_loss_member = bound_loss_member + self._compute_bound_loss(raw_logstd)\n                contact_loss_member = contact_loss_member + F.binary_cross_entropy_with_logits(\n                    contact_logits,\n                    c[:, target_idx],\n                )\n                termination_loss_member = termination_loss_member + F.binary_cross_entropy_with_logits(\n                    term_logits,\n                    t[:, target_idx],\n                )\n                input_state = self.reduce_state(\n                    self.expand_output_state(self.denormalize_output_state(pred_sample))\n                ).unsqueeze(1)\n\n            denom = max(1, forecast_horizon)\n            state_losses.append(state_loss_member / denom)\n            sequence_losses.append(torch.tensor(0.0, device=states.device))\n            bound_losses.append(bound_loss_member / denom)\n            contact_losses.append(contact_loss_member / denom)\n            termination_losses.append(termination_loss_member / denom)\n\n        zero = torch.tensor(0.0, device=states.device)\n        return {\n            "state_loss": torch.stack(state_losses).mean(),\n            "sequence_loss": torch.stack(sequence_losses).mean(),\n            "bound_loss": torch.stack(bound_losses).mean(),\n            "kl_loss": zero,\n            "extension_loss": zero,\n            "contact_loss": torch.stack(contact_losses).mean(),\n            "termination_loss": torch.stack(termination_losses).mean(),\n        }\n\n    def compute_loss(\n        self,\n        states: torch.Tensor,\n        actions: torch.Tensor,\n        next_states: torch.Tensor,\n        contacts: torch.Tensor,\n        terminations: torch.Tensor,\n        bootstrap: bool = True,\n    ) -> dict[str, torch.Tensor]:\n        losses = self._compute_reference_autoregressive_loss(states, actions, next_states, contacts, terminations, bootstrap)\n        total_loss = (\n            self.cfg.state_loss_weight * losses["state_loss"]\n            + self.cfg.sequence_loss_weight * losses["sequence_loss"]\n            + self.cfg.bound_loss_weight * losses["bound_loss"]\n            + self.cfg.kl_loss_weight * losses["kl_loss"]\n            + self.cfg.extension_loss_weight * losses["extension_loss"]\n            + self.cfg.contact_loss_weight * losses["contact_loss"]\n            + self.cfg.termination_loss_weight * losses["termination_loss"]\n        )\n        return {"total_loss": total_loss, **losses}\n\n    @torch.no_grad()\n    def predict(\n        self,\n        state_hist: torch.Tensor,\n        action_hist: torch.Tensor,\n        model_ids: torch.Tensor | None = None,\n    ) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:\n        means = []\n        logstds = []\n        contacts = []\n        terms = []\n        for member in self.members:\n            mean, logstd, contact, term = self._member_prediction(member, state_hist, action_hist)\n            means.append(mean)\n            logstds.append(logstd)\n            contacts.append(contact)\n            terms.append(term)\n        mean_stack = torch.stack(means, dim=0)\n        logstd_stack = torch.stack(logstds, dim=0)\n        contact_stack = torch.stack(contacts, dim=0)\n        term_stack = torch.stack(terms, dim=0)\n\n        if model_ids is None:\n            model_ids = torch.randint(0, self.cfg.ensemble_size, (state_hist.shape[0],), device=state_hist.device)\n        gather_idx = model_ids.view(1, -1, 1)\n        chosen_mean = mean_stack.gather(0, gather_idx.expand(1, -1, self.cfg.output_state_dim))[0]\n        chosen_contact = contact_stack.gather(0, gather_idx.expand(1, -1, self.cfg.contact_dim))[0]\n        chosen_term = term_stack.gather(0, gather_idx.expand(1, -1, self.cfg.termination_dim))[0]\n\n        raw_members = self.denormalize_output_state(mean_stack)\n        epistemic = raw_members.std(dim=0).mean(dim=-1)\n        aleatoric = torch.exp(logstd_stack).mean(dim=(0, 2))\n        next_state = self.expand_output_state(self.denormalize_output_state(chosen_mean))\n        return next_state, aleatoric, epistemic, chosen_contact, chosen_term\n\n    def checkpoint(\n        self,\n        optimizer: torch.optim.Optimizer | None,\n        iteration: int,\n        infos: dict[str, Any] | None = None,\n    ) -> dict[str, Any]:\n        return {\n            "model_type": "go2_proprioceptive",\n            "system_dynamics_state_dict": self.state_dict(),\n            "system_dynamics_optimizer_state_dict": optimizer.state_dict() if optimizer is not None else None,\n            "iter": iteration,\n            "infos": {\n                **(infos or {}),\n                "model_type": "go2_proprioceptive",\n                "proprioceptive_dynamics_config": asdict(self.cfg),\n                "input_state_layout": "full_state[..., 3:45]",\n                "output_state_layout": "full 45-dim Go2 RWM state",\n            },\n        }\n\n\ndef load_proprioceptive_dynamics_checkpoint(\n    path: str | Path,\n    device: torch.device | str,\n) -> tuple[ProprioceptiveSystemDynamicsEnsemble, dict[str, Any]]:\n    checkpoint = torch.load(path, map_location=device, weights_only=False)\n    infos = checkpoint.get("infos") or {}\n    cfg_dict = infos.get("proprioceptive_dynamics_config") or infos.get("reduced_input_dynamics_config")\n    if cfg_dict is None:\n        raise ValueError(\n            f"Checkpoint {path} does not contain infos[\'proprioceptive_dynamics_config\']."\n        )\n    for key in ("dropped_state_indices", "output_dropped_state_indices", "dropped_action_indices"):\n        if isinstance(cfg_dict.get(key), list):\n            cfg_dict[key] = tuple(cfg_dict[key])\n    cfg = ProprioceptiveDynamicsConfig(**cfg_dict)\n    dynamics = ProprioceptiveSystemDynamicsEnsemble(cfg).to(device)\n    dynamics.load_state_dict(checkpoint["system_dynamics_state_dict"], strict=False)\n    dynamics.eval()\n    return dynamics, checkpoint\n',
    'scripts/reinforcement_learning/rwm_dataset/train_world_model_offline_go2_proprioceptive.py': '"""Train a Go2 offline RWM with a true 42-dim state input.\n\nThe model receives ``full_state[..., 3:45]`` plus the 12-d action history and\npredicts the original 45-d next state, contacts, and termination.\n"""\n\nfrom __future__ import annotations\n\nimport json\nimport sys\nimport time\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Any\n\nimport torch\nimport tqdm\nfrom omegaconf import OmegaConf\n\nREPO_ROOT = Path(__file__).resolve().parents[3]\nif str(REPO_ROOT) not in sys.path:\n    sys.path.insert(0, str(REPO_ROOT))\n\nfrom scripts.reinforcement_learning.rwm_dataset.dataset import OfflineSamplerConfig, OfflineSequenceSampler, load_mixed_dataset\nfrom scripts.reinforcement_learning.rwm_dataset.metrics import autoregressive_rollout_metrics\nfrom scripts.reinforcement_learning.rwm_dataset.proprioceptive_dynamics import (\n    ProprioceptiveDynamicsConfig,\n    ProprioceptiveSystemDynamicsEnsemble,\n)\nfrom scripts.reinforcement_learning.rwm_dataset.action_mask import mask_dataset_actions, normalize_action_mask_indices\nfrom scripts.reinforcement_learning.rwm_dataset.broken_go2 import go2_joint_names_to_action_indices\nfrom scripts.reinforcement_learning.rwm_dataset.joint_feature_mask import (\n    GO2_BASE_LIN_VEL_STATE_INDICES,\n    go2_joint_names_to_policy_obs_indices,\n    go2_joint_names_to_rwm_state_indices,\n    indices_to_keep,\n)\nfrom scripts.reinforcement_learning.rwm_dataset.train_world_model_offline_go2 import (\n    ScalarLogger,\n    _load_config,\n    _obs_stats,\n    _parse_args,\n    _save_checkpoint,\n    _train_with_micro_batches,\n)\nfrom scripts.reinforcement_learning.rwm_flashsac.utils import configure_low_thread_env, resolve_repo_path, set_seed\n\n\ndef _cfg_list(value: Any) -> tuple[Any, ...]:\n    if value is None:\n        return ()\n    if isinstance(value, str):\n        return tuple(item for item in value.replace(",", " ").split() if item)\n    return tuple(value)\n\n\ndef main() -> None:\n    configure_low_thread_env()\n    args = _parse_args()\n    cfg = _load_config(args)\n    masked_joint_names = tuple(str(name) for name in _cfg_list(cfg.get("masked_joint_names", [])) if str(name))\n    masked_state_indices = go2_joint_names_to_rwm_state_indices(masked_joint_names)\n    masked_action_indices = go2_joint_names_to_action_indices(masked_joint_names)\n    masked_policy_obs_indices = go2_joint_names_to_policy_obs_indices(masked_joint_names)\n\n    configured_input_drop = normalize_action_mask_indices(\n        cfg.system_dynamics.get("dropped_state_indices", GO2_BASE_LIN_VEL_STATE_INDICES),\n        action_dim=45,\n    )\n    configured_output_drop = normalize_action_mask_indices(\n        cfg.system_dynamics.get("output_dropped_state_indices", []),\n        action_dim=45,\n    )\n    input_dropped_state_indices = tuple(\n        sorted(set(GO2_BASE_LIN_VEL_STATE_INDICES) | set(configured_input_drop) | set(masked_state_indices))\n    )\n    output_dropped_state_indices = tuple(sorted(set(configured_output_drop) | set(masked_state_indices)))\n    action_mask_indices_cfg = normalize_action_mask_indices(cfg.get("action_mask_indices", []), action_dim=12)\n    action_mask_indices_cfg = tuple(sorted(set(action_mask_indices_cfg) | set(masked_action_indices)))\n    policy_observation_mask_indices = tuple(\n        sorted(\n            set(normalize_action_mask_indices(cfg.get("policy_observation_mask_indices", []), action_dim=48))\n            | set(masked_policy_obs_indices)\n        )\n    )\n\n    OmegaConf.update(cfg, "action_mask_indices", list(action_mask_indices_cfg), merge=True)\n    OmegaConf.update(cfg, "masked_joint_names", list(masked_joint_names), merge=True)\n    OmegaConf.update(cfg, "policy_observation_mask_indices", list(policy_observation_mask_indices), merge=True)\n    OmegaConf.update(cfg, "system_dynamics.full_state_dim", 45, merge=True)\n    OmegaConf.update(cfg, "system_dynamics.full_action_dim", 12, merge=True)\n    OmegaConf.update(cfg, "system_dynamics.input_state_dim", 45 - len(input_dropped_state_indices), merge=True)\n    OmegaConf.update(cfg, "system_dynamics.output_state_dim", 45 - len(output_dropped_state_indices), merge=True)\n    OmegaConf.update(cfg, "system_dynamics.dropped_state_indices", list(input_dropped_state_indices), merge=True)\n    OmegaConf.update(\n        cfg,\n        "system_dynamics.output_dropped_state_indices",\n        list(output_dropped_state_indices),\n        merge=True,\n    )\n    OmegaConf.update(cfg, "system_dynamics.dropped_action_indices", list(action_mask_indices_cfg), merge=True)\n    OmegaConf.update(cfg, "system_dynamics.action_dim", 12 - len(action_mask_indices_cfg), merge=True)\n    OmegaConf.update(cfg, "system_dynamics.model_type", "go2_proprioceptive", merge=True)\n    OmegaConf.resolve(cfg)\n\n    set_seed(int(cfg.seed))\n    device = torch.device(str(cfg.device) if torch.cuda.is_available() or not str(cfg.device).startswith("cuda") else "cpu")\n\n    dataset_path = resolve_repo_path(str(cfg.dataset_path))\n    dataset = load_mixed_dataset(dataset_path)\n    action_mask_indices = normalize_action_mask_indices(cfg.get("action_mask_indices", []))\n    action_mask_indices = mask_dataset_actions(dataset, action_mask_indices)\n    sampler_cfg = OfflineSamplerConfig(\n        history_horizon=int(cfg.system_dynamics.history_horizon),\n        forecast_horizon=int(cfg.system_dynamics.forecast_horizon),\n        train_fraction=float(cfg.train_fraction),\n        seed=int(cfg.seed),\n    )\n    sampler = OfflineSequenceSampler(dataset, sampler_cfg)\n    state_mean, state_std, action_mean, action_std = sampler.stats()\n    input_state_keep = indices_to_keep(input_dropped_state_indices, dim=sampler.state_dim)\n    output_state_keep = indices_to_keep(output_dropped_state_indices, dim=sampler.state_dim)\n    action_keep = indices_to_keep(action_mask_indices, dim=sampler.action_dim)\n    normalizer = {\n        "full_state_mean": state_mean,\n        "full_state_std": state_std,\n        "output_state_mean": state_mean[list(output_state_keep)],\n        "output_state_std": state_std[list(output_state_keep)],\n        "input_state_mean": state_mean[list(input_state_keep)],\n        "input_state_std": state_std[list(input_state_keep)],\n        "full_action_mean": action_mean,\n        "full_action_std": action_std,\n        "action_mean": action_mean[list(action_keep)],\n        "action_std": action_std[list(action_keep)],\n        **_obs_stats(dataset),\n    }\n\n    dynamics_cfg = ProprioceptiveDynamicsConfig(\n        input_state_dim=int(cfg.system_dynamics.input_state_dim),\n        output_state_dim=int(cfg.system_dynamics.output_state_dim),\n        action_dim=int(cfg.system_dynamics.action_dim),\n        full_state_dim=sampler.state_dim,\n        full_action_dim=sampler.action_dim,\n        contact_dim=sampler.contact_dim,\n        termination_dim=sampler.termination_dim,\n        ensemble_size=int(cfg.system_dynamics.ensemble_size),\n        history_horizon=int(cfg.system_dynamics.history_horizon),\n        forecast_horizon=int(cfg.system_dynamics.forecast_horizon),\n        hidden_size=int(cfg.system_dynamics.hidden_size),\n        num_layers=int(cfg.system_dynamics.num_layers),\n        state_loss_weight=float(cfg.system_dynamics.get("state_loss_weight", 1.0)),\n        sequence_loss_weight=float(cfg.system_dynamics.get("sequence_loss_weight", 1.0)),\n        bound_loss_weight=float(cfg.system_dynamics.get("bound_loss_weight", 1.0)),\n        kl_loss_weight=float(cfg.system_dynamics.get("kl_loss_weight", 0.1)),\n        extension_loss_weight=float(cfg.system_dynamics.get("extension_loss_weight", 1.0)),\n        contact_loss_weight=float(cfg.system_dynamics.contact_loss_weight),\n        termination_loss_weight=float(cfg.system_dynamics.termination_loss_weight),\n        loss_mode=str(cfg.system_dynamics.get("loss_mode", "reference_autoregressive_mse")),\n        dropped_state_indices=tuple(input_dropped_state_indices),\n        output_dropped_state_indices=tuple(output_dropped_state_indices),\n        dropped_action_indices=tuple(action_mask_indices),\n    )\n    dynamics = ProprioceptiveSystemDynamicsEnsemble(dynamics_cfg).to(device)\n    dynamics.set_normalizers(state_mean, state_std, action_mean, action_std)\n    optimizer = torch.optim.Adam(\n        dynamics.parameters(),\n        lr=float(cfg.learning_rate),\n        weight_decay=float(cfg.weight_decay),\n    )\n\n    save_base = resolve_repo_path(str(cfg.save_dir))\n    save_root = save_base / datetime.now().strftime("%Y-%m-%d_%H-%M-%S")\n    save_root.mkdir(parents=True, exist_ok=True)\n    OmegaConf.save(cfg, save_root / "go2_offline_world_model_proprioceptive.yaml")\n    with (save_root / "dataset_metadata.json").open("w", encoding="utf-8") as f:\n        json.dump(sampler.metadata(), f, indent=2, default=str)\n    logger = ScalarLogger(save_root)\n\n    print(f"[Go2-OfflineRWM-Proprioceptive] dataset={dataset_path}")\n    print(f"[Go2-OfflineRWM-Proprioceptive] save_root={save_root}")\n    print(\n        "[Go2-OfflineRWM-Proprioceptive] model input: "\n        f"state_dim={dynamics_cfg.input_state_dim}, action_dim={dynamics_cfg.action_dim}; "\n        f"dropped_state_indices={list(input_dropped_state_indices)}, "\n        f"dropped_action_indices={list(action_mask_indices)}"\n    )\n    print(\n        "[Go2-OfflineRWM-Proprioceptive] model output: "\n        f"state_dim={dynamics_cfg.output_state_dim}, "\n        f"output_dropped_state_indices={list(output_dropped_state_indices)}, contact, termination"\n    )\n    print(f"[Go2-OfflineRWM-Proprioceptive] device={device}, transitions={sampler.num_transitions}")\n    print(f"[Go2-OfflineRWM-Proprioceptive] train_sequences={sampler.train_indices.shape[0]}, val_sequences={sampler.val_indices.shape[0]}")\n    print(f"[Go2-OfflineRWM-Proprioceptive] batch_size={int(cfg.batch_size)}, micro_batch_size={int(cfg.micro_batch_size)}")\n    print(f"[Go2-OfflineRWM-Proprioceptive] action_mask_indices={list(action_mask_indices)}")\n    print(f"[Go2-OfflineRWM-Proprioceptive] masked_joint_names={list(masked_joint_names)}")\n    print(f"[Go2-OfflineRWM-Proprioceptive] policy_observation_mask_indices={list(policy_observation_mask_indices)}")\n\n    start_time = time.perf_counter()\n    latest_metrics: dict[str, float] = {}\n    for iteration in tqdm.trange(1, int(cfg.max_iterations) + 1, smoothing=0.1, mininterval=0.5):\n        loss_values = _train_with_micro_batches(\n            dynamics=dynamics,\n            optimizer=optimizer,\n            sampler=sampler,\n            batch_size=int(cfg.batch_size),\n            micro_batch_size=int(cfg.micro_batch_size),\n            device=device,\n        )\n\n        latest_metrics = {\n            "Model/train_total_loss": float(loss_values["total_loss"]),\n            "Model/train_state_loss": float(loss_values["state_loss"]),\n            "Model/train_sequence_loss": float(loss_values["sequence_loss"]),\n            "Model/train_bound_loss": float(loss_values.get("bound_loss", 0.0)),\n            "Model/train_kl_loss": float(loss_values.get("kl_loss", 0.0)),\n            "Model/train_extension_loss": float(loss_values.get("extension_loss", 0.0)),\n            "Model/train_contact_loss": float(loss_values["contact_loss"]),\n            "Model/train_termination_loss": float(loss_values["termination_loss"]),\n            "Dataset/replay_size": float(sampler.num_transitions),\n            "Dataset/train_sequences": float(sampler.train_indices.shape[0]),\n            "Dataset/val_sequences": float(sampler.val_indices.shape[0]),\n        }\n\n        if iteration % int(cfg.log_interval) == 0 or iteration == 1:\n            dynamics.eval()\n            with torch.no_grad():\n                eval_batch_size = min(int(cfg.batch_size), int(cfg.micro_batch_size))\n                eval_batch = sampler.sample(eval_batch_size, device=device, split="val")\n                eval_loss = dynamics.compute_loss(*eval_batch, bootstrap=False)\n                available_rollout = max(1, sampler.num_time_steps - dynamics.cfg.history_horizon)\n                rollout_horizon = min(100, available_rollout)\n                rollout_batch = sampler.sample(\n                    min(eval_batch_size, 512),\n                    device=device,\n                    split="val",\n                    forecast_horizon=max(rollout_horizon, int(cfg.system_dynamics.forecast_horizon)),\n                )\n                rollout = autoregressive_rollout_metrics(\n                    dynamics,\n                    rollout_batch,\n                    rollout_horizon=rollout_horizon,\n                )\n            latest_metrics.update(\n                {\n                    "Model/eval_state_loss": float(eval_loss["state_loss"].detach().cpu()),\n                    "Model/eval_sequence_loss": float(eval_loss["sequence_loss"].detach().cpu()),\n                    "Model/eval_bound_loss": float(eval_loss.get("bound_loss", torch.tensor(0.0)).detach().cpu()),\n                    "Model/eval_kl_loss": float(eval_loss.get("kl_loss", torch.tensor(0.0)).detach().cpu()),\n                    "Model/eval_extension_loss": float(eval_loss.get("extension_loss", torch.tensor(0.0)).detach().cpu()),\n                    "Model/eval_contact_loss": float(eval_loss["contact_loss"].detach().cpu()),\n                    "Model/eval_termination_loss": float(eval_loss["termination_loss"].detach().cpu()),\n                }\n            )\n            latest_metrics.update({f"Model/{key}": value for key, value in rollout.items()})\n            latest_metrics["Perf/elapsed_seconds"] = float(time.perf_counter() - start_time)\n            logger.log(latest_metrics, iteration)\n            interesting = {\n                key: latest_metrics[key]\n                for key in (\n                    "Model/train_state_loss",\n                    "Model/eval_state_loss",\n                    "Model/traj_autoregressive_error",\n                    "Model/epistemic_uncertainty_mean",\n                    "Dataset/replay_size",\n                )\n                if key in latest_metrics\n            }\n            print(f"[Go2-OfflineRWM-Proprioceptive] iter={iteration} {interesting}")\n\n        if iteration % int(cfg.save_interval) == 0:\n            _save_checkpoint(\n                save_root=save_root,\n                dynamics=dynamics,\n                optimizer=optimizer,\n                iteration=iteration,\n                infos={\n                    "dataset_path": str(dataset_path),\n                    "action_mask_indices": list(action_mask_indices),\n                    "policy_action_mask_indices": list(action_mask_indices),\n                    "world_model_action_mask_indices": list(action_mask_indices),\n                    "masked_joint_names": list(masked_joint_names),\n                    "dropped_state_indices": list(input_dropped_state_indices),\n                    "output_dropped_state_indices": list(output_dropped_state_indices),\n                    "dropped_action_indices": list(action_mask_indices),\n                    "policy_observation_mask_indices": list(policy_observation_mask_indices),\n                    "metrics": dict(latest_metrics),\n                    **sampler.metadata(),\n                },\n                normalizer=normalizer,\n                cfg=cfg,\n                dataset_metadata=sampler.metadata(),\n            )\n\n    _save_checkpoint(\n        save_root=save_root,\n        dynamics=dynamics,\n        optimizer=optimizer,\n        iteration=int(cfg.max_iterations),\n        infos={\n            "dataset_path": str(dataset_path),\n            "action_mask_indices": list(action_mask_indices),\n            "policy_action_mask_indices": list(action_mask_indices),\n            "world_model_action_mask_indices": list(action_mask_indices),\n            "masked_joint_names": list(masked_joint_names),\n            "dropped_state_indices": list(input_dropped_state_indices),\n            "output_dropped_state_indices": list(output_dropped_state_indices),\n            "dropped_action_indices": list(action_mask_indices),\n            "policy_observation_mask_indices": list(policy_observation_mask_indices),\n            "metrics": dict(latest_metrics),\n            **sampler.metadata(),\n        },\n        normalizer=normalizer,\n        cfg=cfg,\n        dataset_metadata=sampler.metadata(),\n    )\n    with (save_root / "final_metrics.json").open("w", encoding="utf-8") as f:\n        json.dump(latest_metrics, f, indent=2)\n    logger.close()\n    print(f"[Go2-OfflineRWM-Proprioceptive] saved final checkpoint: {save_root / f\'model_{int(cfg.max_iterations)}.pt\'}")\n\n\nif __name__ == "__main__":\n    main()\n',
    'scripts/reinforcement_learning/rwm_flashsac/utils.py': '"""Utilities shared by Go2 FlashSAC-RWM scripts."""\n\nfrom __future__ import annotations\n\nimport os\nimport random\nfrom pathlib import Path\nfrom typing import Any\n\nimport gymnasium as gym\nimport numpy as np\nimport torch\nfrom gymnasium.vector.utils import batch_space\nfrom omegaconf import DictConfig, OmegaConf\n\nfrom flash_rl.agents.flashSAC.agent import FlashSACConfig\nfrom scripts.reinforcement_learning.rwm_dataset.action_mask import normalize_action_mask_indices\nfrom scripts.reinforcement_learning.rwm_dataset.joint_feature_mask import mask_array_features_np\n\n\nREPO_ROOT = Path(__file__).resolve().parents[3]\nDEFAULT_CONFIG_PATH = Path(__file__).resolve().parent / "configs" / "go2_flashsac_rwm.yaml"\n\n\ndef resolve_repo_path(path: str | Path) -> Path:\n    p = Path(path).expanduser()\n    return p if p.is_absolute() else (REPO_ROOT / p).resolve()\n\n\ndef load_config(config_path: str | Path | None = None, overrides: list[str] | None = None) -> DictConfig:\n    cfg = OmegaConf.load(config_path or DEFAULT_CONFIG_PATH)\n    if overrides:\n        override_cfg = OmegaConf.from_dotlist(overrides)\n        cfg = OmegaConf.merge(cfg, override_cfg)\n    OmegaConf.resolve(cfg)\n    return cfg\n\n\ndef set_seed(seed: int) -> None:\n    random.seed(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n    if torch.cuda.is_available():\n        torch.cuda.manual_seed_all(seed)\n\n\ndef select_device(device_type: str | None = None) -> str:\n    if device_type:\n        if device_type.startswith("cuda") and torch.cuda.is_available():\n            return device_type if ":" in device_type else "cuda:0"\n        if device_type.startswith("cpu"):\n            return "cpu"\n    return "cuda:0" if torch.cuda.is_available() else "cpu"\n\n\ndef make_vector_spaces(num_envs: int, obs_dim: int = 48, action_dim: int = 12) -> tuple[gym.Space, gym.Space]:\n    single_obs = gym.spaces.Box(low=-np.inf, high=np.inf, shape=(obs_dim,), dtype=np.float32)\n    single_action = gym.spaces.Box(low=-1.0, high=1.0, shape=(action_dim,), dtype=np.float32)\n    return batch_space(single_obs, num_envs), batch_space(single_action, num_envs)\n\n\ndef get_world_model_action_masks(cfg: Any, action_dim: int) -> tuple[tuple[int, ...], tuple[int, ...]]:\n    policy_mask = normalize_action_mask_indices(\n        OmegaConf.select(cfg, "world_model.policy_action_mask_indices") or [],\n        action_dim=action_dim,\n    )\n    world_model_mask = normalize_action_mask_indices(\n        OmegaConf.select(cfg, "world_model.world_model_action_mask_indices") or [],\n        action_dim=action_dim,\n    )\n    if len(policy_mask) >= action_dim:\n        raise ValueError("policy_action_mask_indices cannot mask every action dimension.")\n    return policy_mask, world_model_mask\n\n\ndef get_world_model_policy_observation_mask(cfg: Any, observation_dim: int) -> tuple[int, ...]:\n    return normalize_action_mask_indices(\n        OmegaConf.select(cfg, "world_model.policy_observation_mask_indices") or [],\n        action_dim=observation_dim,\n    )\n\n\ndef apply_policy_observation_mask_np(observations: np.ndarray, mask_indices: tuple[int, ...]) -> np.ndarray:\n    return mask_array_features_np(observations, mask_indices)\n\n\ndef get_world_model_broken_joint_names(\n    cfg: Any,\n    override: list[str] | tuple[str, ...] | None = None,\n) -> tuple[str, ...]:\n    if override is not None:\n        values = override\n    else:\n        values = OmegaConf.select(cfg, "world_model.broken_joint_names") or []\n    if isinstance(values, str):\n        values = values.replace(",", " ").split()\n    return tuple(dict.fromkeys(str(name) for name in values if str(name)))\n\n\ndef expand_policy_actions_np(\n    actions: np.ndarray,\n    action_dim: int,\n    policy_action_mask_indices: tuple[int, ...],\n    world_model_action_mask_indices: tuple[int, ...],\n) -> np.ndarray:\n    if not policy_action_mask_indices:\n        if actions.shape[-1] != action_dim:\n            raise ValueError(f"Action dim mismatch: expected {action_dim}, got {actions.shape[-1]}.")\n        full_actions = actions.astype(np.float32, copy=True)\n    else:\n        expected_dim = action_dim - len(policy_action_mask_indices)\n        if actions.shape[-1] != expected_dim:\n            raise ValueError(f"Policy action dim mismatch: expected {expected_dim}, got {actions.shape[-1]}.")\n        full_actions = np.zeros((*actions.shape[:-1], action_dim), dtype=np.float32)\n        kept_indices = [idx for idx in range(action_dim) if idx not in set(policy_action_mask_indices)]\n        full_actions[..., kept_indices] = actions.astype(np.float32, copy=False)\n\n    zero_indices = sorted(set(policy_action_mask_indices) | set(world_model_action_mask_indices))\n    if zero_indices:\n        full_actions[..., zero_indices] = 0.0\n    return full_actions\n\n\ndef make_flashsac_config(cfg: Any, device: str) -> FlashSACConfig:\n    agent_cfg = OmegaConf.to_container(cfg.agent, resolve=True, throw_on_missing=True)\n    if not isinstance(agent_cfg, dict):\n        raise ValueError("cfg.agent must be a mapping")\n    agent_cfg = {str(k): v for k, v in agent_cfg.items()}\n    agent_cfg["device_type"] = device\n    if device.startswith("cpu"):\n        agent_cfg["buffer_device_type"] = "cpu"\n        agent_cfg["use_amp"] = False\n    elif not str(agent_cfg.get("buffer_device_type", "")).startswith("cuda"):\n        agent_cfg["buffer_device_type"] = device\n    return FlashSACConfig(**agent_cfg)  # type: ignore[arg-type]\n\n\ndef save_config(cfg: Any, path: str | Path) -> None:\n    path = Path(path)\n    path.parent.mkdir(parents=True, exist_ok=True)\n    OmegaConf.save(config=cfg, f=path)\n\n\ndef scalarize(value: Any) -> float | int | Any:\n    if isinstance(value, torch.Tensor):\n        if value.numel() == 0:\n            return 0.0\n        return float(value.float().mean().item())\n    if isinstance(value, np.ndarray):\n        if value.size == 0:\n            return 0.0\n        return float(value.astype(np.float32).mean())\n    if isinstance(value, (float, int)):\n        return value\n    return value\n\n\ndef latest_checkpoint(root: str | Path) -> Path:\n    root = Path(root)\n    candidates = [p for p in root.glob("step*") if p.is_dir()]\n    if not candidates:\n        raise FileNotFoundError(f"No step* checkpoint directories found under {root}")\n\n    def step_num(path: Path) -> int:\n        try:\n            return int(path.name.replace("step", ""))\n        except ValueError:\n            return -1\n\n    return max(candidates, key=step_num)\n\n\ndef configure_low_thread_env() -> None:\n    os.environ.setdefault("OMP_NUM_THREADS", "2")\n    os.environ.setdefault("MKL_NUM_THREADS", "2")\n    os.environ.setdefault("NUMEXPR_NUM_THREADS", "2")\n',
    'scripts/reinforcement_learning/rwm_flashsac/world_model_env.py': '"""Gymnasium VectorEnv wrapper around the learned Go2 RWM dynamics."""\n\nfrom __future__ import annotations\n\nfrom collections import deque\nfrom dataclasses import dataclass\nfrom typing import Any\n\nimport gymnasium as gym\nimport numpy as np\nimport torch\nfrom gymnasium.vector import VectorEnv\nfrom gymnasium.vector.utils import batch_space\n\nfrom scripts.reinforcement_learning.rwm.dynamics import SequenceReplayBuffer, SystemDynamicsEnsemble\nfrom scripts.reinforcement_learning.rwm_dataset.action_mask import normalize_action_mask_indices\nfrom scripts.reinforcement_learning.rwm_dataset.joint_feature_mask import mask_tensor_features_t\nfrom src.tasks.rwm_velocity.mdp.extractors import make_go2_policy_obs\nfrom src.tasks.rwm_velocity.mdp.rewards import (\n    Go2RWMRewardState,\n    bad_orientation_from_state,\n    compute_go2_imagination_reward,\n)\n\n\n@dataclass\nclass FlashSACWorldModelEnvConfig:\n    num_envs: int = 4096\n    max_episode_length: int = 1000\n    step_dt: float = 0.02\n    command_resample_interval_min: int = 150\n    command_resample_interval_max: int = 400\n    lin_vel_x_min: float = -1.0\n    lin_vel_x_max: float = 2.0\n    lin_vel_y_min: float = -1.0\n    lin_vel_y_max: float = 1.0\n    ang_vel_z_min: float = -1.0\n    ang_vel_z_max: float = 1.0\n    rel_standing_envs: float = 0.05\n    uncertainty_penalty_weight: float = -1.0\n    policy_action_mask_indices: tuple[int, ...] = ()\n    world_model_action_mask_indices: tuple[int, ...] = ()\n    policy_observation_mask_indices: tuple[int, ...] = ()\n    broken_joint_names: tuple[str, ...] = ()\n\n\nclass Go2RWMFlashSACWorldModelEnv(VectorEnv):\n    """VectorEnv that produces synthetic Go2 transitions from a frozen RWM."""\n\n    metadata: dict[str, Any] = {}\n\n    def __init__(\n        self,\n        dynamics: SystemDynamicsEnsemble,\n        dataset: SequenceReplayBuffer,\n        cfg: FlashSACWorldModelEnvConfig,\n        device: torch.device | str,\n    ) -> None:\n        self.system_dynamics = dynamics.to(device).eval()\n        self.dataset = dataset\n        self.cfg = cfg\n        self.num_envs = cfg.num_envs\n        self._device = torch.device(device)\n        self._full_obs_dim = 48\n        self._policy_observation_mask_indices = normalize_action_mask_indices(\n            cfg.policy_observation_mask_indices,\n            action_dim=self._full_obs_dim,\n        )\n        self._obs_dim = self._full_obs_dim - len(self._policy_observation_mask_indices)\n        self._full_action_dim = int(getattr(dynamics.cfg, "full_action_dim", dynamics.cfg.action_dim))\n        self._model_action_dim = int(dynamics.cfg.action_dim)\n        self._policy_action_mask_indices = normalize_action_mask_indices(\n            cfg.policy_action_mask_indices,\n            action_dim=self._full_action_dim,\n        )\n        self._world_model_action_mask_indices = normalize_action_mask_indices(\n            cfg.world_model_action_mask_indices,\n            action_dim=self._full_action_dim,\n        )\n        if len(self._policy_action_mask_indices) >= self._full_action_dim:\n            raise ValueError("policy_action_mask_indices cannot mask every action dimension.")\n        self._policy_action_dim = self._full_action_dim - len(self._policy_action_mask_indices)\n        self._kept_action_indices = tuple(\n            idx for idx in range(self._full_action_dim) if idx not in set(self._policy_action_mask_indices)\n        )\n        self._kept_action_indices_t = torch.tensor(self._kept_action_indices, dtype=torch.long, device=self._device)\n        self._full_action_zero_indices = tuple(\n            sorted(set(self._policy_action_mask_indices) | set(self._world_model_action_mask_indices))\n        )\n        self._full_action_zero_indices_t = torch.tensor(\n            self._full_action_zero_indices,\n            dtype=torch.long,\n            device=self._device,\n        )\n        self.single_observation_space = gym.spaces.Box(\n            low=-np.inf,\n            high=np.inf,\n            shape=(self._obs_dim,),\n            dtype=np.float32,\n        )\n        self.observation_space = batch_space(self.single_observation_space, self.num_envs)\n        self.single_action_space = gym.spaces.Box(\n            low=-1.0,\n            high=1.0,\n            shape=(self._policy_action_dim,),\n            dtype=np.float32,\n        )\n        self.action_space = batch_space(self.single_action_space, self.num_envs)\n\n        self.episode_length_buf = torch.zeros(self.num_envs, dtype=torch.long, device=self._device)\n        self.model_ids = torch.randint(0, dynamics.ensemble_size, (self.num_envs,), device=self._device)\n        self.command_intervals = torch.zeros(self.num_envs, dtype=torch.long, device=self._device)\n        self.command = torch.zeros(self.num_envs, 3, device=self._device)\n        self.state_history: torch.Tensor\n        self.action_history: torch.Tensor\n        self.reward_state = Go2RWMRewardState.create(\n            num_envs=self.num_envs,\n            action_dim=self._full_action_dim,\n            device=self._device,\n            step_dt=cfg.step_dt,\n        )\n        self.reward_state.weights.uncertainty = cfg.uncertainty_penalty_weight\n        self._ep_returns = torch.zeros(self.num_envs, device=self._device)\n        self._ep_lengths = torch.zeros(self.num_envs, dtype=torch.long, device=self._device)\n        self._reward_buffer: deque[float] = deque(maxlen=100)\n        self._length_buffer: deque[float] = deque(maxlen=100)\n        self._latest_log: dict[str, float] = {}\n        self._reset_all()\n\n    @property\n    def full_action_dim(self) -> int:\n        return self._full_action_dim\n\n    @property\n    def policy_action_dim(self) -> int:\n        return self._policy_action_dim\n\n    def _sample_commands(self, env_ids: torch.Tensor) -> None:\n        n = len(env_ids)\n        if n == 0:\n            return\n        r = torch.rand(n, 3, device=self._device)\n        self.command[env_ids, 0] = self.cfg.lin_vel_x_min + r[:, 0] * (\n            self.cfg.lin_vel_x_max - self.cfg.lin_vel_x_min\n        )\n        self.command[env_ids, 1] = self.cfg.lin_vel_y_min + r[:, 1] * (\n            self.cfg.lin_vel_y_max - self.cfg.lin_vel_y_min\n        )\n        self.command[env_ids, 2] = self.cfg.ang_vel_z_min + r[:, 2] * (\n            self.cfg.ang_vel_z_max - self.cfg.ang_vel_z_min\n        )\n        standing = torch.rand(n, device=self._device) < self.cfg.rel_standing_envs\n        self.command[env_ids[standing]] = 0.0\n        self.command_intervals[env_ids] = torch.randint(\n            self.cfg.command_resample_interval_min,\n            self.cfg.command_resample_interval_max + 1,\n            (n,),\n            device=self._device,\n        )\n\n    def _apply_full_action_zero_mask(self, actions: torch.Tensor) -> torch.Tensor:\n        if self._full_action_zero_indices_t.numel() > 0:\n            actions[..., self._full_action_zero_indices_t] = 0.0\n        return actions\n\n    def _expand_policy_actions(self, actions: torch.Tensor) -> torch.Tensor:\n        if actions.shape[-1] != self._policy_action_dim:\n            raise ValueError(\n                f"Action dim mismatch: expected policy action dim {self._policy_action_dim}, "\n                f"got {int(actions.shape[-1])}."\n            )\n        actions = torch.clamp(actions, -1.0, 1.0)\n        if not self._policy_action_mask_indices:\n            full_actions = actions.clone()\n        else:\n            full_actions = torch.zeros(\n                *actions.shape[:-1],\n                self._full_action_dim,\n                dtype=actions.dtype,\n                device=actions.device,\n            )\n            full_actions[..., self._kept_action_indices_t] = actions\n        return self._apply_full_action_zero_mask(full_actions)\n\n    def _reset_histories(self, env_ids: torch.Tensor) -> None:\n        states, actions = self.dataset.sample_initial_history(\n            batch_size=len(env_ids),\n            history_horizon=self.system_dynamics.cfg.history_horizon,\n            device=self._device,\n        )\n        self.state_history[env_ids] = states\n        self.action_history[env_ids] = self._apply_full_action_zero_mask(actions)\n\n    def _reset_all(self) -> None:\n        self.state_history, self.action_history = self.dataset.sample_initial_history(\n            batch_size=self.num_envs,\n            history_horizon=self.system_dynamics.cfg.history_horizon,\n            device=self._device,\n        )\n        self.action_history = self._apply_full_action_zero_mask(self.action_history)\n        env_ids = torch.arange(self.num_envs, device=self._device)\n        self.episode_length_buf.zero_()\n        self.model_ids = torch.randint(0, self.system_dynamics.ensemble_size, (self.num_envs,), device=self._device)\n        self._sample_commands(env_ids)\n        self.reward_state.last_joint_vel = self.state_history[:, -1, 21:33].clone()\n        self.reward_state.last_action = self.action_history[:, -1].clone()\n        self._ep_returns.zero_()\n        self._ep_lengths.zero_()\n\n    def _reset_idx(self, env_ids: torch.Tensor) -> None:\n        if len(env_ids) == 0:\n            return\n        self._reset_histories(env_ids)\n        self.episode_length_buf[env_ids] = 0\n        self.model_ids[env_ids] = torch.randint(\n            0,\n            self.system_dynamics.ensemble_size,\n            (len(env_ids),),\n            device=self._device,\n        )\n        self._sample_commands(env_ids)\n        self.reward_state.last_joint_vel[env_ids] = self.state_history[env_ids, -1, 21:33]\n        self.reward_state.last_action[env_ids] = self.action_history[env_ids, -1]\n\n    def _current_obs_t(self) -> torch.Tensor:\n        full_obs = make_go2_policy_obs(self.state_history[:, -1], self.command, self.action_history[:, -1])\n        return mask_tensor_features_t(full_obs, self._policy_observation_mask_indices)\n\n    def _current_obs_np(self) -> np.ndarray:\n        return self._current_obs_t().detach().cpu().numpy().astype(np.float32)\n\n    def reset(\n        self,\n        *,\n        seed: int | None = None,\n        options: dict[str, Any] | None = None,\n    ) -> tuple[np.ndarray, dict[str, Any]]:\n        del options\n        if seed is not None:\n            torch.manual_seed(seed)\n            np.random.seed(seed)\n        self._reset_all()\n        self._reward_buffer.clear()\n        self._length_buffer.clear()\n        return self._current_obs_np(), {}\n\n    def _episode_info(self) -> dict[str, float]:\n        info: dict[str, float] = dict(self._latest_log)\n        if self._reward_buffer:\n            info["Train/mean_reward"] = float(np.mean(self._reward_buffer))\n            info["Train/mean_episode_length"] = float(np.mean(self._length_buffer))\n        return info\n\n    def step(self, actions: np.ndarray | torch.Tensor) -> tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray, dict[str, Any]]:\n        if isinstance(actions, np.ndarray):\n            policy_action_t = torch.from_numpy(actions).to(self._device).float()\n        else:\n            policy_action_t = actions.to(self._device).float()\n        action_t = self._expand_policy_actions(policy_action_t)\n\n        self.action_history = torch.cat([self.action_history[:, 1:], action_t.unsqueeze(1)], dim=1)\n        with torch.no_grad():\n            next_state, _aleatoric, epistemic, contact_logits, term_logits = self.system_dynamics.predict(\n                self.state_history,\n                self.action_history,\n                self.model_ids,\n            )\n        foot_contact = (torch.sigmoid(contact_logits) > 0.5).float()\n        rewards, reward_terms = compute_go2_imagination_reward(\n            state=next_state,\n            action=action_t,\n            command=self.command,\n            foot_contact=foot_contact,\n            episode_length=self.episode_length_buf,\n            reward_state=self.reward_state,\n            epistemic_uncertainty=epistemic,\n        )\n\n        self.state_history = torch.cat([self.state_history[:, 1:], next_state.unsqueeze(1)], dim=1)\n        final_obs_t = make_go2_policy_obs(next_state, self.command, action_t)\n        self.episode_length_buf += 1\n        self._ep_returns += rewards\n        self._ep_lengths += 1\n\n        predicted_done = torch.sigmoid(term_logits).squeeze(-1) > 0.5\n        bad_orientation = bad_orientation_from_state(next_state)\n        time_outs = self.episode_length_buf >= self.cfg.max_episode_length\n        terminated = predicted_done | bad_orientation\n        truncated = time_outs\n        dones = terminated | truncated\n\n        resample_ids = (self.episode_length_buf % self.command_intervals == 0).nonzero(as_tuple=False).squeeze(-1)\n        self._sample_commands(resample_ids)\n\n        done_ids = dones.nonzero(as_tuple=False).squeeze(-1)\n        if len(done_ids) > 0:\n            self._reward_buffer.extend(self._ep_returns[done_ids].detach().cpu().tolist())\n            self._length_buffer.extend(self._ep_lengths[done_ids].detach().cpu().tolist())\n            self._ep_returns[done_ids] = 0.0\n            self._ep_lengths[done_ids] = 0\n            self._reset_idx(done_ids)\n\n        self._latest_log = {\n            "Imagination/epistemic_uncertainty": float(epistemic.mean().detach().cpu()),\n            "Imagination/predicted_done": float(predicted_done.float().mean().detach().cpu()),\n            "Imagination/bad_orientation": float(bad_orientation.float().mean().detach().cpu()),\n            "Imagination/num_valid_imagination_envs": float((~dones).float().sum().detach().cpu()),\n        }\n        for key, value in reward_terms.items():\n            self._latest_log[f"Imagination/{key}"] = float(value.mean().detach().cpu())\n\n        next_obs = self._current_obs_np()\n        final_obs = final_obs_t.detach().cpu().numpy().astype(np.float32)\n        infos = {\n            "final_obs": final_obs,\n            "episode_info": self._episode_info(),\n        }\n        return (\n            next_obs,\n            rewards.detach().cpu().numpy().astype(np.float32),\n            terminated.detach().cpu().numpy(),\n            truncated.detach().cpu().numpy(),\n            infos,\n        )\n\n    def close(self, **kwargs: Any) -> None:\n        return None\n',
    'scripts/reinforcement_learning/rwm_flashsac/world_model_env_proprioceptive.py': '"""Helpers for Go2 RWM FlashSAC policies with proprioceptive actor input."""\n\nfrom __future__ import annotations\n\nimport numpy as np\nimport torch\n\n\nPROPRIOCEPTIVE_ACTOR_OBS_DIM = 45\nCRITIC_OBS_DIM_FULL_RWM = 48\n\n\ndef proprioceptive_obs_np(full_rwm_obs: np.ndarray) -> np.ndarray:\n    """Actor view: RWM obs without base_lin_vel[0:3]."""\n\n    return full_rwm_obs[:, 3:].astype(np.float32, copy=False)\n\n\ndef proprioceptive_obs_t(full_rwm_obs: torch.Tensor) -> torch.Tensor:\n    """Torch actor view: RWM obs without base_lin_vel[0:3]."""\n\n    return full_rwm_obs[:, 3:]\n\n\n__all__ = [\n    "PROPRIOCEPTIVE_ACTOR_OBS_DIM",\n    "CRITIC_OBS_DIM_FULL_RWM",\n    "proprioceptive_obs_np",\n    "proprioceptive_obs_t",\n]\n',
    'scripts/reinforcement_learning/rwm_flashsac/agent_proprioceptive.py': '"""FlashSAC agent with a proprioceptive actor observation."""\n\nfrom __future__ import annotations\n\nfrom typing import Any, MutableMapping, cast\n\nimport gymnasium as gym\nimport torch\n\nfrom flash_rl.agents.flashSAC.agent import (\n    FlashSACAgent,\n    FlashSACConfig,\n    _sample_flashsac_actions,\n    _update_networks,\n)\nfrom flash_rl.types import NDArray, Tensor\nfrom scripts.reinforcement_learning.rwm_flashsac.world_model_env_proprioceptive import (\n    PROPRIOCEPTIVE_ACTOR_OBS_DIM,\n    proprioceptive_obs_t,\n)\n\n\nclass FlashSACProprioceptiveAgent(FlashSACAgent):\n    """Use full 48-dim RWM obs for critic and 45-dim proprioception for actor."""\n\n    def sample_actions(\n        self,\n        interaction_step: int,\n        prev_transition: MutableMapping[str, Tensor],\n        training: bool,\n    ) -> Tensor:\n        del interaction_step\n        temperature = 1.0 if training else 0.0\n        observations = torch.as_tensor(\n            prev_transition["next_observation"],\n            dtype=torch.float32,\n            device=self._device,\n        )\n        actor_observations = proprioceptive_obs_t(observations)\n\n        with torch.no_grad():\n            (\n                self._cached_noise,\n                actions,\n                self._cur_noise_repeat_count,\n                self._cur_noise_repeat_n,\n            ) = _sample_flashsac_actions(\n                actor=self._actor,\n                noise=self._cached_noise,\n                observations=actor_observations,\n                temperature=temperature,\n                cur_count=self._cur_noise_repeat_count,\n                cur_n=self._cur_noise_repeat_n,\n                zeta_cdf=self._zeta_cdf,\n            )\n        return actions.cpu().numpy()\n\n    def update(self) -> dict[str, Any]:\n        batch = cast(dict[str, torch.Tensor], self._replay_buffer.sample())\n        for key, value in batch.items():\n            batch[key] = value.to(self._device, non_blocking=True)\n\n        batch["actor_observation"] = proprioceptive_obs_t(batch["observation"])\n        batch["actor_next_observation"] = proprioceptive_obs_t(batch["next_observation"])\n\n        if self._cfg.normalize_reward:\n            assert self.reward_normalizer is not None\n            batch["reward"] = self.reward_normalizer.normalize_rewards(batch["reward"])\n\n        update_info_raw = _update_networks(\n            batch=batch,\n            actor=self._actor,\n            critic=self._critic,\n            target_critic=self._target_critic,\n            temperature=self._temperature,\n            cfg=self._cfg,\n            do_actor_update=(self._update_step % self._cfg.actor_update_period == 0),\n            device=self._device,\n            grad_scaler=self._grad_scaler,\n        )\n        self._update_step += 1\n\n        update_info: dict[str, float] = {}\n        for key, value in update_info_raw.items():\n            if isinstance(value, torch.Tensor):\n                update_info[key] = value.item()\n            elif not isinstance(value, dict):\n                update_info[key] = float(value)\n        return update_info\n\n\ndef create_go2_flashsac_proprioceptive_agent(\n    observation_space: gym.Space[NDArray],\n    action_space: gym.Space[NDArray],\n    cfg: FlashSACConfig,\n) -> FlashSACAgent:\n    obs_dim = int(observation_space.shape[-1])\n    actor_obs_dim = obs_dim - 3\n    if actor_obs_dim <= 0:\n        raise ValueError(f"Expected RWM observation dim > 3, got {obs_dim}.")\n    env_info: dict[str, Any] = {"actor_observation_size": (actor_obs_dim,)}\n    return FlashSACProprioceptiveAgent(observation_space, action_space, env_info, cfg)\n',
    'scripts/reinforcement_learning/rwm_flashsac/train_flashsac_world_model_go2.py': '"""Train Go2 FlashSAC entirely inside the learned RWM imagination env."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport sys\nimport time\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Any\n\nimport numpy as np\nimport torch\nimport tqdm\nfrom omegaconf import OmegaConf\n\nREPO_ROOT = Path(__file__).resolve().parents[3]\nif str(REPO_ROOT) not in sys.path:\n    sys.path.insert(0, str(REPO_ROOT))\n\nfrom scripts.reinforcement_learning.rwm.dynamics import SequenceReplayBuffer, load_dynamics_checkpoint\nfrom scripts.reinforcement_learning.rwm_flashsac.agent import create_go2_flashsac_agent\nfrom scripts.reinforcement_learning.rwm_flashsac.utils import (\n    configure_low_thread_env,\n    load_config,\n    make_flashsac_config,\n    resolve_repo_path,\n    save_config,\n    select_device,\n    set_seed,\n)\nfrom scripts.reinforcement_learning.rwm_flashsac.world_model_env import (\n    FlashSACWorldModelEnvConfig,\n    Go2RWMFlashSACWorldModelEnv,\n)\n\n\nclass ScalarLogger:\n    def __init__(self, log_dir: Path, enabled: bool = True) -> None:\n        self._writer = None\n        self._values: dict[str, list[float]] = {}\n        if enabled:\n            from torch.utils.tensorboard import SummaryWriter\n\n            self._writer = SummaryWriter(log_dir=str(log_dir / "tb"))\n\n    def update(self, values: dict[str, Any]) -> None:\n        for key, value in values.items():\n            if isinstance(value, torch.Tensor):\n                value = float(value.detach().float().mean().cpu())\n            elif isinstance(value, np.ndarray):\n                value = float(value.astype(np.float32).mean()) if value.size else 0.0\n            elif isinstance(value, (float, int, np.floating, np.integer)):\n                value = float(value)\n            else:\n                continue\n            self._values.setdefault(key, []).append(float(value))\n\n    def log(self, step: int) -> dict[str, float]:\n        averages = {key: float(np.mean(vals)) for key, vals in self._values.items() if vals}\n        if self._writer is not None:\n            for key, value in averages.items():\n                self._writer.add_scalar(key, value, step)\n            self._writer.flush()\n        self._values.clear()\n        return averages\n\n    def close(self) -> None:\n        if self._writer is not None:\n            self._writer.close()\n\n\ndef _parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(allow_abbrev=False)\n    parser.add_argument("--config_path", default=None)\n    parser.add_argument("--model_resume_path", default=None)\n    parser.add_argument("--dataset_path", default=None)\n    parser.add_argument("--device", default=None)\n    parser.add_argument("--num_imagination_envs", type=int, default=None)\n    parser.add_argument("--num_env_steps", type=int, default=None)\n    parser.add_argument("--save_path", default=None)\n    parser.add_argument("--save_replay_buffer", action=argparse.BooleanOptionalAction, default=None)\n    parser.add_argument("--overrides", action="append", default=[])\n    return parser.parse_args()\n\n\ndef _apply_arg_overrides(cfg: Any, args: argparse.Namespace) -> Any:\n    updates: list[str] = list(args.overrides or [])\n    if args.model_resume_path is not None:\n        updates.append(f"model_resume_path={args.model_resume_path}")\n    if args.dataset_path is not None:\n        updates.append(f"dataset_path={args.dataset_path}")\n    if args.num_imagination_envs is not None:\n        updates.append(f"num_imagination_envs={args.num_imagination_envs}")\n    if args.num_env_steps is not None:\n        updates.append(f"num_env_steps={args.num_env_steps}")\n    if args.save_path is not None:\n        updates.append(f"save_path={args.save_path}")\n    if args.save_replay_buffer is not None:\n        updates.append(f"save_replay_buffer={str(args.save_replay_buffer).lower()}")\n    if not updates:\n        return cfg\n    return OmegaConf.merge(cfg, OmegaConf.from_dotlist(updates))\n\n\ndef _save_checkpoint(agent: Any, save_dir: Path, cfg: Any, save_replay: bool) -> None:\n    agent.save(str(save_dir))\n    save_config(cfg, save_dir / "rwm_flashsac_config.yaml")\n    if save_replay:\n        agent.save_replay_buffer(str(save_dir))\n\n\ndef main() -> None:\n    configure_low_thread_env()\n    args = _parse_args()\n    cfg = load_config(args.config_path)\n    cfg = _apply_arg_overrides(cfg, args)\n    OmegaConf.resolve(cfg)\n\n    device = select_device(args.device or cfg.agent.device_type)\n    set_seed(int(cfg.seed))\n\n    model_path = resolve_repo_path(str(cfg.model_resume_path))\n    dataset_path = resolve_repo_path(str(cfg.dataset_path))\n    dynamics, _checkpoint = load_dynamics_checkpoint(model_path, device=device)\n    dataset = SequenceReplayBuffer.load(dataset_path, device=device)\n\n    checkpoint_infos = _checkpoint.get("infos") or {}\n    checkpoint_action_mask = checkpoint_infos.get("action_mask_indices") or []\n    checkpoint_world_model_mask = checkpoint_infos.get("world_model_action_mask_indices") or checkpoint_action_mask\n    checkpoint_policy_mask = checkpoint_infos.get("policy_action_mask_indices") or checkpoint_world_model_mask\n    checkpoint_policy_observation_mask = checkpoint_infos.get("policy_observation_mask_indices") or []\n    checkpoint_broken_joints = (\n        checkpoint_infos.get("broken_pd_joint_names")\n        or checkpoint_infos.get("broken_joint_names")\n        or []\n    )\n    configured_policy_mask = OmegaConf.select(cfg, "world_model.policy_action_mask_indices") or []\n    configured_wm_mask = OmegaConf.select(cfg, "world_model.world_model_action_mask_indices") or []\n    configured_policy_observation_mask = OmegaConf.select(cfg, "world_model.policy_observation_mask_indices") or []\n    configured_broken_joints = OmegaConf.select(cfg, "world_model.broken_joint_names") or []\n    if checkpoint_policy_mask and not configured_policy_mask:\n        OmegaConf.update(\n            cfg,\n            "world_model.policy_action_mask_indices",\n            list(checkpoint_policy_mask),\n            merge=True,\n        )\n    if checkpoint_world_model_mask and not configured_wm_mask:\n        OmegaConf.update(\n            cfg,\n            "world_model.world_model_action_mask_indices",\n            list(checkpoint_world_model_mask),\n            merge=True,\n        )\n    if checkpoint_policy_observation_mask and not configured_policy_observation_mask:\n        OmegaConf.update(\n            cfg,\n            "world_model.policy_observation_mask_indices",\n            list(checkpoint_policy_observation_mask),\n            merge=True,\n        )\n    if checkpoint_broken_joints and not configured_broken_joints:\n        OmegaConf.update(\n            cfg,\n            "world_model.broken_joint_names",\n            list(checkpoint_broken_joints),\n            merge=True,\n        )\n\n    wm_cfg_dict = OmegaConf.to_container(cfg.world_model, resolve=True, throw_on_missing=True)\n    assert isinstance(wm_cfg_dict, dict)\n    wm_cfg = FlashSACWorldModelEnvConfig(**{str(k): v for k, v in wm_cfg_dict.items()})\n    wm_cfg.num_envs = int(cfg.num_imagination_envs)\n    env = Go2RWMFlashSACWorldModelEnv(dynamics=dynamics, dataset=dataset, cfg=wm_cfg, device=device)\n    policy_action_dim = int(env.single_action_space.shape[0])\n\n    agent_cfg = make_flashsac_config(cfg, device=device)\n    agent = create_go2_flashsac_agent(env.observation_space, env.action_space, agent_cfg)\n\n    save_path = str(cfg.save_path).replace("TIMESTAMP", datetime.now().strftime("%Y-%m-%d_%H-%M-%S"))\n    save_root = resolve_repo_path(save_path)\n    save_root.mkdir(parents=True, exist_ok=True)\n    save_config(cfg, save_root / "rwm_flashsac_config.yaml")\n    logger = ScalarLogger(save_root, enabled=str(cfg.logger_type).lower() == "tensorboard")\n\n    num_envs = int(cfg.num_imagination_envs)\n    total_interaction_steps = max(1, int(int(cfg.num_env_steps) // num_envs))\n    update_counter = 0.0\n    observations, _ = env.reset(seed=int(cfg.seed))\n    transition: dict[str, Any] | None = None\n    collection_time_acc = 0.0\n    learning_time_acc = 0.0\n    env_steps_since_log = 0\n\n    print(f"[Go2-FlashSAC-RWM] model={model_path}")\n    print(f"[Go2-FlashSAC-RWM] dataset={dataset_path}")\n    print(f"[Go2-FlashSAC-RWM] save_root={save_root}")\n    print(f"[Go2-FlashSAC-RWM] device={device}, num_envs={num_envs}, interaction_steps={total_interaction_steps}")\n    print(f"[Go2-FlashSAC-RWM] full_action_dim={env.full_action_dim}, policy_action_dim={policy_action_dim}")\n    print(\n        "[Go2-FlashSAC-RWM] "\n        f"policy_action_mask_indices={list(wm_cfg.policy_action_mask_indices)}, "\n        f"world_model_action_mask_indices={list(wm_cfg.world_model_action_mask_indices)}, "\n        f"policy_observation_mask_indices={list(wm_cfg.policy_observation_mask_indices)}"\n    )\n\n    for interaction_step in tqdm.tqdm(range(1, total_interaction_steps + 1), smoothing=0.1, mininterval=0.5):\n        env_step = interaction_step * num_envs\n        start = time.perf_counter()\n        if agent.can_start_training() and transition is not None:\n            actions = agent.sample_actions(interaction_step, prev_transition=transition, training=True)\n        else:\n            actions = np.random.uniform(-1.0, 1.0, size=(num_envs, policy_action_dim)).astype(np.float32)\n\n        next_observations, rewards, terminateds, truncateds, infos = env.step(actions)\n        next_buffer_observations = next_observations.copy()\n        final_obs = infos.get("final_obs")\n        if final_obs is not None:\n            done_mask = np.logical_or(terminateds, truncateds)\n            next_buffer_observations[done_mask] = final_obs[done_mask]\n\n        transition = {\n            "observation": observations,\n            "action": actions,\n            "reward": rewards,\n            "terminated": terminateds,\n            "truncated": truncateds,\n            "next_observation": next_buffer_observations,\n        }\n        agent.process_transition(transition)\n        transition["next_observation"] = next_observations\n        observations = next_observations\n        collection_time_acc += time.perf_counter() - start\n        env_steps_since_log += num_envs\n        if "episode_info" in infos:\n            logger.update(infos["episode_info"])\n\n        if agent.can_start_training():\n            start = time.perf_counter()\n            update_counter += float(cfg.updates_per_interaction_step)\n            while update_counter >= 1.0:\n                logger.update(agent.update())\n                update_counter -= 1.0\n            learning_time_acc += time.perf_counter() - start\n\n        if int(cfg.logging_per_interaction_step) and interaction_step % int(cfg.logging_per_interaction_step) == 0:\n            total_time = collection_time_acc + learning_time_acc\n            if total_time > 0.0:\n                logger.update(\n                    {\n                        "Perf/total_fps": env_steps_since_log / total_time,\n                        "Perf/collection_time": collection_time_acc,\n                        "Perf/learning_time": learning_time_acc,\n                    }\n                )\n            logged = logger.log(env_step)\n            interesting = {\n                k: logged[k]\n                for k in (\n                    "Train/mean_reward",\n                    "Train/mean_episode_length",\n                    "critic/loss",\n                    "actor/loss",\n                    "Imagination/epistemic_uncertainty",\n                    "Imagination/track_linear_velocity",\n                    "Imagination/action_rate_l2",\n                    "Perf/total_fps",\n                )\n                if k in logged\n            }\n            print(f"[Go2-FlashSAC-RWM] step={interaction_step} env_step={env_step} {interesting}")\n            collection_time_acc = 0.0\n            learning_time_acc = 0.0\n            env_steps_since_log = 0\n\n        if int(cfg.save_checkpoint_per_interaction_step) and interaction_step % int(cfg.save_checkpoint_per_interaction_step) == 0:\n            _save_checkpoint(\n                agent,\n                save_root / f"step{interaction_step}",\n                cfg,\n                save_replay=bool(cfg.save_replay_buffer),\n            )\n\n    _save_checkpoint(\n        agent,\n        save_root / f"step{total_interaction_steps}",\n        cfg,\n        save_replay=bool(cfg.save_replay_buffer),\n    )\n    logger.close()\n    env.close()\n\n\nif __name__ == "__main__":\n    main()\n',
    'scripts/reinforcement_learning/rwm_flashsac/play_flashsac_go2_mjlab.py': '"""Visualize a Go2 FlashSAC-RWM policy in the real mjlab simulator."""\n\nfrom __future__ import annotations\n\nimport argparse\nimport os\nimport random\nimport sys\nfrom pathlib import Path\nfrom typing import Any, Literal\n\nimport numpy as np\nimport torch\n\nREPO_ROOT = Path(__file__).resolve().parents[3]\nif str(REPO_ROOT) not in sys.path:\n    sys.path.insert(0, str(REPO_ROOT))\n\nfrom mjlab.rl import RslRlVecEnvWrapper\nfrom mjlab.viewer import NativeMujocoViewer, ViserPlayViewer\n\nfrom scripts.reinforcement_learning.rwm_flashsac.agent import create_go2_flashsac_agent\nfrom scripts.reinforcement_learning.rwm_dataset.broken_go2 import (\n    apply_go2_broken_pd_joints,\n    apply_go2_pd_joint_strength_scales,\n)\nfrom scripts.reinforcement_learning.rwm_flashsac.utils import (\n    apply_policy_observation_mask_np,\n    configure_low_thread_env,\n    expand_policy_actions_np,\n    get_world_model_broken_joint_names,\n    get_world_model_action_masks,\n    get_world_model_policy_observation_mask,\n    load_config,\n    make_flashsac_config,\n    make_vector_spaces,\n    resolve_repo_path,\n    select_device,\n    set_seed,\n)\n\n\ndef _parse_args() -> argparse.Namespace:\n    parser = argparse.ArgumentParser(allow_abbrev=False)\n    parser.add_argument("--checkpoint_path", required=True)\n    parser.add_argument("--config_path", default=None)\n    parser.add_argument("--task", default="Unitree-Go2-Flat-RWM-Pretrain-Ens")\n    parser.add_argument("--device", default=None)\n    parser.add_argument("--num_envs", type=int, default=1)\n    parser.add_argument("--seed", type=int, default=123)\n    parser.add_argument("--viewer", choices=("auto", "native", "viser"), default="auto")\n    parser.add_argument("--frame_rate", type=float, default=60.0)\n    parser.add_argument("--fixed_command", type=float, nargs=3, metavar=("VX", "VY", "YAW"), default=None)\n    parser.add_argument(\n        "--command_sequence",\n        nargs="+",\n        default=None,\n        help=\'Optional command schedule, e.g. "0.3,0,0" "0.5,0,0" "0.5,0,0.3".\',\n    )\n    parser.add_argument("--command_switch_steps", type=int, default=500)\n    parser.add_argument("--random_command", action="store_true")\n    parser.add_argument("--random_lin_vel_x", type=float, nargs=2, default=(0.0, 1.0), metavar=("MIN", "MAX"))\n    parser.add_argument("--random_lin_vel_y", type=float, nargs=2, default=(-0.3, 0.3), metavar=("MIN", "MAX"))\n    parser.add_argument("--random_ang_vel_z", type=float, nargs=2, default=(-0.5, 0.5), metavar=("MIN", "MAX"))\n    parser.add_argument("--random_stand_prob", type=float, default=0.0)\n    parser.add_argument("--clean", action=argparse.BooleanOptionalAction, default=True)\n    parser.add_argument("--no_terminations", action="store_true")\n    parser.add_argument("--broken_joint_names", nargs="*", default=None)\n    parser.add_argument(\n        "--joint_strength_scales",\n        nargs="*",\n        default=(),\n        metavar="JOINT=SCALE",\n        help="Per-joint actuator strength scales for mjlab play, e.g. RR_calf_joint=0.5.",\n    )\n    parser.add_argument("--overrides", action="append", default=[])\n    return parser.parse_args()\n\n\ndef _disable_randomization(env_cfg: Any) -> None:\n    env_cfg.events.pop("push_robot", None)\n    for event_name in ("foot_friction", "encoder_bias", "base_com"):\n        env_cfg.events.pop(event_name, None)\n    for group_name in ("actor", "critic"):\n        obs_group = env_cfg.observations.get(group_name)\n        if obs_group is not None:\n            obs_group.enable_corruption = False\n    if hasattr(env_cfg, "curriculum"):\n        env_cfg.curriculum = {}\n    if hasattr(env_cfg, "curriculums"):\n        env_cfg.curriculums = {}\n\n\ndef _parse_command_sequence(values: list[str] | None) -> list[tuple[float, float, float]]:\n    if not values:\n        return []\n    commands: list[tuple[float, float, float]] = []\n    for value in values:\n        parts = value.replace(";", ",").split(",")\n        if len(parts) != 3:\n            raise ValueError(f"Expected command triplet \'vx,vy,yaw\', got: {value}")\n        commands.append((float(parts[0]), float(parts[1]), float(parts[2])))\n    return commands\n\n\ndef _parse_joint_strength_scales(spec: list[str] | tuple[str, ...]) -> dict[str, float]:\n    scales: dict[str, float] = {}\n    for item in spec:\n        raw = str(item).strip()\n        if not raw:\n            continue\n        if "=" in raw:\n            name, value = raw.split("=", maxsplit=1)\n        elif ":" in raw:\n            name, value = raw.split(":", maxsplit=1)\n        else:\n            raise ValueError(f"Invalid joint strength scale {raw!r}; expected JOINT=SCALE.")\n        name = name.strip()\n        if not name:\n            raise ValueError(f"Invalid joint strength scale {raw!r}; joint name is empty.")\n        scale = float(value)\n        if scale < 0.0 or scale > 1.0:\n            raise ValueError(f"Joint strength scale for {name!r} must be in [0, 1], got {scale}.")\n        scales[name] = scale\n    return scales\n\n\ndef _configure_command_ranges(\n    env_cfg: Any,\n    fixed_command: tuple[float, float, float] | None,\n    command_sequence: list[tuple[float, float, float]],\n    random_ranges: tuple[tuple[float, float], tuple[float, float], tuple[float, float]] | None = None,\n) -> None:\n    if "twist" not in env_cfg.commands:\n        return\n    twist_cmd = env_cfg.commands["twist"]\n    commands = command_sequence or ([fixed_command] if fixed_command is not None else [])\n    if random_ranges is not None:\n        twist_cmd.ranges.lin_vel_x = random_ranges[0]\n        twist_cmd.ranges.lin_vel_y = random_ranges[1]\n        twist_cmd.ranges.ang_vel_z = random_ranges[2]\n    elif commands:\n        # Viser command sliders require a positive symmetric max even when the\n        # actual command is fixed to zero on an axis.\n        max_x = max(0.1, max(abs(cmd[0]) for cmd in commands))\n        max_y = max(0.1, max(abs(cmd[1]) for cmd in commands))\n        max_yaw = max(0.1, max(abs(cmd[2]) for cmd in commands))\n        twist_cmd.ranges.lin_vel_x = (-max_x, max_x)\n        twist_cmd.ranges.lin_vel_y = (-max_y, max_y)\n        twist_cmd.ranges.ang_vel_z = (-max_yaw, max_yaw)\n    if hasattr(twist_cmd.ranges, "heading"):\n        twist_cmd.ranges.heading = None\n    if hasattr(twist_cmd, "heading_command"):\n        twist_cmd.heading_command = False\n    if hasattr(twist_cmd, "rel_standing_envs"):\n        twist_cmd.rel_standing_envs = 0.0\n    if hasattr(twist_cmd, "rel_heading_envs"):\n        twist_cmd.rel_heading_envs = 0.0\n    if hasattr(twist_cmd, "init_velocity_prob"):\n        twist_cmd.init_velocity_prob = 0.0\n\n\ndef _force_fixed_command(env: Any, fixed_command: tuple[float, float, float] | None) -> None:\n    if fixed_command is None:\n        return\n    try:\n        command = env.unwrapped.command_manager.get_term("twist")\n    except Exception:\n        return\n    value = torch.tensor(fixed_command, dtype=torch.float32, device=env.unwrapped.device)\n    if hasattr(command, "vel_command_b"):\n        command.vel_command_b[:, :] = value\n    if hasattr(command, "is_standing_env"):\n        command.is_standing_env[:] = False\n    if hasattr(command, "is_heading_env"):\n        command.is_heading_env[:] = False\n\n\ndef _resolve_viewer(viewer: Literal["auto", "native", "viser"]) -> Literal["native", "viser"]:\n    if viewer != "auto":\n        return viewer\n    has_display = bool(os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"))\n    return "native" if has_display else "viser"\n\n\nclass FlashSACPolicyAdapter:\n    def __init__(\n        self,\n        agent: Any,\n        device: str,\n        fixed_command: tuple[float, float, float] | None,\n        command_sequence: list[tuple[float, float, float]],\n        command_switch_steps: int,\n        random_command: bool,\n        random_ranges: tuple[tuple[float, float], tuple[float, float], tuple[float, float]],\n        random_stand_prob: float,\n        env: Any,\n        full_action_dim: int,\n        policy_action_mask_indices: tuple[int, ...],\n        world_model_action_mask_indices: tuple[int, ...],\n        policy_observation_mask_indices: tuple[int, ...],\n    ):\n        self.agent = agent\n        self.device = device\n        self.fixed_command = fixed_command\n        self.command_sequence = command_sequence\n        self.command_switch_steps = max(1, int(command_switch_steps))\n        self.random_command = random_command\n        self.random_ranges = random_ranges\n        self.random_stand_prob = float(random_stand_prob)\n        self.env = env\n        self.full_action_dim = int(full_action_dim)\n        self.policy_action_mask_indices = policy_action_mask_indices\n        self.world_model_action_mask_indices = world_model_action_mask_indices\n        self.policy_observation_mask_indices = policy_observation_mask_indices\n        self.step_count = 0\n        self.sampled_command: tuple[float, float, float] | None = None\n\n    def _current_command(self) -> tuple[float, float, float] | None:\n        if self.random_command:\n            if self.sampled_command is None or self.step_count % self.command_switch_steps == 0:\n                if random.random() < self.random_stand_prob:\n                    self.sampled_command = (0.0, 0.0, 0.0)\n                else:\n                    self.sampled_command = (\n                        random.uniform(*self.random_ranges[0]),\n                        random.uniform(*self.random_ranges[1]),\n                        random.uniform(*self.random_ranges[2]),\n                    )\n                print(f"[Go2-FlashSAC-RWM-Play] sampled_command={self.sampled_command}")\n            return self.sampled_command\n        if self.command_sequence:\n            index = (self.step_count // self.command_switch_steps) % len(self.command_sequence)\n            return self.command_sequence[index]\n        return self.fixed_command\n\n    def __call__(self, obs: Any) -> torch.Tensor:\n        command = self._current_command()\n        _force_fixed_command(self.env, command)\n        actor_obs = obs["actor"]\n        if command is not None:\n            actor_obs = actor_obs.clone()\n            actor_obs[:, 9:12] = torch.tensor(command, dtype=actor_obs.dtype, device=actor_obs.device)\n        obs_np = actor_obs.detach().cpu().numpy().astype(np.float32)\n        obs_np = apply_policy_observation_mask_np(obs_np, self.policy_observation_mask_indices)\n        actions_np = self.agent.sample_actions(\n            interaction_step=0,\n            prev_transition={"next_observation": obs_np},\n            training=False,\n        )\n        actions_np = expand_policy_actions_np(\n            actions_np,\n            action_dim=self.full_action_dim,\n            policy_action_mask_indices=self.policy_action_mask_indices,\n            world_model_action_mask_indices=self.world_model_action_mask_indices,\n        )\n        self.step_count += 1\n        return torch.from_numpy(actions_np).to(device=self.device, dtype=torch.float32)\n\n    def reset(self) -> None:\n        self.step_count = 0\n        self.sampled_command = None\n        _force_fixed_command(self.env, self._current_command())\n\n\ndef main() -> None:\n    configure_low_thread_env()\n    args = _parse_args()\n    resolved_viewer = _resolve_viewer(args.viewer)\n    if resolved_viewer == "native":\n        os.environ.setdefault("MUJOCO_GL", "glfw")\n    else:\n        os.environ.setdefault("MUJOCO_GL", "egl")\n\n    checkpoint_path = resolve_repo_path(args.checkpoint_path)\n    config_path = Path(args.config_path).expanduser() if args.config_path else checkpoint_path / "rwm_flashsac_config.yaml"\n    if not config_path.is_absolute():\n        config_path = resolve_repo_path(config_path)\n    cfg = load_config(config_path, overrides=args.overrides)\n\n    device = select_device(args.device or cfg.agent.device_type)\n    set_seed(args.seed)\n    fixed_command = tuple(args.fixed_command) if args.fixed_command is not None else None\n    command_sequence = _parse_command_sequence(args.command_sequence)\n    random_ranges = (\n        tuple(args.random_lin_vel_x),\n        tuple(args.random_lin_vel_y),\n        tuple(args.random_ang_vel_z),\n    )\n    broken_joint_names = get_world_model_broken_joint_names(cfg, args.broken_joint_names)\n    joint_strength_scales = _parse_joint_strength_scales(args.joint_strength_scales)\n\n    import mjlab.tasks  # noqa: F401\n    import src.tasks  # noqa: F401\n    import src.tasks.rwm_velocity  # noqa: F401\n    from mjlab.envs import ManagerBasedRlEnv\n    from mjlab.tasks.registry import load_env_cfg\n    from mjlab.utils.torch import configure_torch_backends\n\n    configure_torch_backends()\n    env_cfg = load_env_cfg(args.task, play=True)\n    env_cfg.scene.num_envs = args.num_envs\n    env_cfg.seed = args.seed\n    env_cfg.auto_reset = True\n    if args.no_terminations:\n        env_cfg.terminations = {}\n    if args.clean:\n        _disable_randomization(env_cfg)\n    if joint_strength_scales:\n        apply_go2_pd_joint_strength_scales(env_cfg, joint_strength_scales)\n    if broken_joint_names:\n        apply_go2_broken_pd_joints(env_cfg, broken_joint_names)\n    _configure_command_ranges(\n        env_cfg,\n        fixed_command,\n        command_sequence,\n        random_ranges=random_ranges if args.random_command else None,\n    )\n\n    env = ManagerBasedRlEnv(cfg=env_cfg, device=device)\n    _force_fixed_command(env, fixed_command)\n    actor_dim = int(env.single_observation_space.spaces["actor"].shape[0])\n    full_action_dim = int(env.single_action_space.shape[0])\n    if actor_dim != 48:\n        env.close()\n        raise RuntimeError(f"Expected 48-dim RWM actor observation, got {actor_dim}.")\n\n    policy_action_mask_indices, world_model_action_mask_indices = get_world_model_action_masks(cfg, full_action_dim)\n    policy_observation_mask_indices = get_world_model_policy_observation_mask(cfg, actor_dim)\n    policy_action_dim = full_action_dim - len(policy_action_mask_indices)\n    policy_observation_dim = actor_dim - len(policy_observation_mask_indices)\n\n    obs_space, action_space = make_vector_spaces(\n        args.num_envs,\n        obs_dim=policy_observation_dim,\n        action_dim=policy_action_dim,\n    )\n    agent_cfg = make_flashsac_config(cfg, device=device)\n    agent = create_go2_flashsac_agent(obs_space, action_space, agent_cfg)\n    agent.load(str(checkpoint_path))\n\n    wrapped_env = RslRlVecEnvWrapper(env, clip_actions=1.0)\n    _force_fixed_command(wrapped_env, fixed_command)\n    policy = FlashSACPolicyAdapter(\n        agent=agent,\n        device=device,\n        fixed_command=fixed_command,\n        command_sequence=command_sequence,\n        command_switch_steps=args.command_switch_steps,\n        random_command=bool(args.random_command),\n        random_ranges=random_ranges,\n        random_stand_prob=args.random_stand_prob,\n        env=wrapped_env,\n        full_action_dim=full_action_dim,\n        policy_action_mask_indices=policy_action_mask_indices,\n        world_model_action_mask_indices=world_model_action_mask_indices,\n        policy_observation_mask_indices=policy_observation_mask_indices,\n    )\n\n    print(f"[Go2-FlashSAC-RWM-Play] checkpoint={checkpoint_path}")\n    print(f"[Go2-FlashSAC-RWM-Play] viewer={resolved_viewer}, device={device}, num_envs={args.num_envs}")\n    print(f"[Go2-FlashSAC-RWM-Play] broken_joint_names={list(broken_joint_names)}")\n    print(f"[Go2-FlashSAC-RWM-Play] joint_strength_scales={joint_strength_scales}")\n    print(\n        "[Go2-FlashSAC-RWM-Play] "\n        f"full_action_dim={full_action_dim}, policy_action_dim={policy_action_dim}, "\n        f"policy_action_mask_indices={list(policy_action_mask_indices)}, "\n        f"world_model_action_mask_indices={list(world_model_action_mask_indices)}, "\n        f"policy_observation_mask_indices={list(policy_observation_mask_indices)}"\n    )\n    if fixed_command is not None:\n        print(f"[Go2-FlashSAC-RWM-Play] fixed_command={fixed_command}")\n    if command_sequence:\n        print(\n            "[Go2-FlashSAC-RWM-Play] command_sequence="\n            f"{command_sequence}, switch_steps={args.command_switch_steps}"\n        )\n    if args.random_command:\n        print(\n            "[Go2-FlashSAC-RWM-Play] random_command=True, "\n            f"switch_steps={args.command_switch_steps}, ranges={random_ranges}, "\n            f"stand_prob={args.random_stand_prob}"\n        )\n\n    if resolved_viewer == "native":\n        NativeMujocoViewer(wrapped_env, policy, frame_rate=args.frame_rate).run()\n    else:\n        ViserPlayViewer(wrapped_env, policy, frame_rate=args.frame_rate).run()\n    wrapped_env.close()\n\n\nif __name__ == "__main__":\n    main()\n',
}


def main() -> None:
    for rel_path, content in FILES.items():
        path = REPO_ROOT / rel_path
        path.parent.mkdir(parents=True, exist_ok=True)
        old = path.read_text() if path.exists() else None
        if old == content:
            print(f"[Go2FullJointMaskRefactor] unchanged: {rel_path}")
            continue
        path.write_text(content)
        action = "updated" if old is not None else "created"
        print(f"[Go2FullJointMaskRefactor] {action}: {rel_path}")
    print("[Go2FullJointMaskRefactor] complete")


if __name__ == "__main__":
    main()
